REPLACE INTO `pages` (`id`,`title`,`slug`,`status`,`sections`,`seo`,`published_at`) VALUES
('99999999-0000-4000-8000-000000000001','About Fabric-Pro','about','published','[{"id":"about-body","type":"rich_text","settings":{"width":"narrow","padding":"md","html":"<p>Fabric-Pro publishes clear, useful coverage for professionals who follow the textile, fabric, apparel material, machinery, sourcing, sustainability, and circular materials sectors.</p><p>Our goal is simple: make important industry updates easy to scan, easy to understand, and easy to revisit.</p><h2>What we cover</h2><ul><li>Textile and fabric industry news</li><li>Machinery, manufacturing, dyeing, finishing, and production updates</li><li>Sustainable fabrics, recycled textiles, and circular supply chains</li><li>Sourcing, supplier, brand, and market developments</li><li>Practical blogs and industry insights</li></ul><h2>Editorial approach</h2><p>Fabric-Pro is built for readable publishing. Articles are written in plain language, organized with clear headings, and supported by SEO-ready metadata so readers and search engines can understand every page.</p>"}}]','{"title":"About Fabric-Pro | Textile Industry News and Insights","description":"Learn about Fabric-Pro, a news and article website covering textile industry updates, fabric innovation, sourcing, machinery, and sustainability."}','2026-06-11 00:00:00');
